mapper.select:
select * from t_order



        and transac_status = #{transac_status}


        and shop_id = #{shop_id}


        and shop_id = #{shopId}


        and order_time >= #{startTime}


        and order_time < #{endTime}


order by order_time desc

    limit #{start},#{pageSize}

select count(*) from t_order

    and merchantId = '1'

        and transac_status = #{transac_status}


        and shop_id = #{shop_id}


        and shop_id = #{shopId}


        and order_time >= #{startTime}


        and order_time < #{endTime}

SELECT COUNT(*) FROM t_order
WHERE merchantId = '1' AND order_time >= #{startTime} AND order_time < #{endTime}

    AND shop_id = #{shopId}


    AND shop_id = #{shop_id}

SELECT COALESCE(NULLIF(TRIM(o.payment_method), ''), '未登记') AS payment_method, COUNT(*) AS order_count, IFNULL(SUM(), 0) AS revenue FROM t_order o WHERE COALESCE(o.pay_time, o.order_time) >= #{startTime} AND COALESCE(o.pay_time, o.order_time) < #{endTime} AND o.merchantId = '1' AND o.transac_status = 'success' AND (o.order_receiving IN ('rec_order', 'off_order') OR o.order_receiving IS NULL)
AND o.shop_id = #{shopId}
GROUP BY COALESCE(NULLIF(TRIM(o.payment_method), ''), '未登记') ORDER BY revenue DESC

SELECT od.cid, c.value AS category_name, SUM(od.total_price) AS total_sales FROM t_order_detail od INNER JOIN t_order o ON od.`mId` = o.id LEFT JOIN t_category c ON od.cid = c.cid WHERE o.order_time >= #{startTime} AND o.order_time < #{endTime} AND od.total_price > 0 AND od.cid IS NOT NULL AND od.cid != '' AND o.transac_status = 'success' AND o.order_receiving IN ('rec_order', 'off_order')
AND o.shop_id = #{shopId}
AND o.shop_id = #{shop_id}
AND od.cid IN
#{cid}
GROUP BY od.cid, c.value ORDER BY total_sales DESC

SELECT
    COALESCE(SUM(o.service_fee), 0) AS total_service_fee,
    COALESCE(SUM(o.discount_amount), 0) AS total_discount_amount,
    COALESCE(SUM(o.sett_amount), 0) AS total_sett_amount
FROM t_order o
WHERE
    o.order_time >= #{startTime}
    AND o.order_time < #{endTime}
    AND o.merchantId = '1'
    AND o.transac_status = 'success'
    AND o.order_receiving IN ('rec_order', 'off_order')

        AND o.shop_id = #{shopId}


        AND o.shop_id = #{shop_id}


        AND o.id IN (
            SELECT DISTINCT od.`mId` FROM t_order_detail od
            WHERE od.cid IN

                #{cid}

        )

SELECT od.name AS dish_name, SUM(od.total_price) AS total_sales, SUM(od.quantity) AS total_quantity FROM t_order_detail od INNER JOIN t_order o ON od.`mId` = o.id WHERE o.order_time >= #{startTime} AND o.order_time < #{endTime} AND ( (od.total_price IS NOT NULL AND od.total_price > 0) OR IFNULL(od.line_type,'') = 'combo_component' ) AND od.name IS NOT NULL AND od.name != '' AND o.transac_status = 'success' AND o.order_receiving IN ('rec_order', 'off_order')
AND o.shop_id = #{shopId}
AND o.shop_id = #{shop_id}
AND od.name IN
#{name}
GROUP BY od.name ORDER BY total_sales DESC

SELECT IF(DAYOFWEEK(o.order_time) = 1, 7, DAYOFWEEK(o.order_time) - 1) AS iso_dow, TRIM(od.name) AS dish_name, SUM(od.quantity) AS total_qty FROM t_order_detail od INNER JOIN t_order o ON od.`mId` = o.id WHERE o.order_time >= #{startTime} AND o.order_time < #{endTime} AND od.quantity IS NOT NULL AND od.quantity > 0 AND ( (od.total_price IS NOT NULL AND od.total_price > 0) OR IFNULL(od.line_type,'') = 'combo_component' ) AND od.name IS NOT NULL AND TRIM(od.name) != '' AND o.transac_status = 'success' AND o.order_receiving IN ('rec_order', 'off_order')
AND o.shop_id = #{shopId}
AND o.shop_id = #{shop_id}
GROUP BY IF(DAYOFWEEK(o.order_time) = 1, 7, DAYOFWEEK(o.order_time) - 1), TRIM(od.name)

SELECT TRIM(od.name) AS dish_name, SUM(od.quantity) AS total_qty FROM t_order_detail od INNER JOIN t_order o ON od.`mId` = o.id WHERE o.order_time >= #{startTime} AND o.order_time < #{endTime} AND od.quantity IS NOT NULL AND od.quantity > 0 AND ( (od.total_price IS NOT NULL AND od.total_price > 0) OR IFNULL(od.line_type,'') = 'combo_component' ) AND od.name IS NOT NULL AND TRIM(od.name) != '' AND o.transac_status = 'success' AND o.order_receiving IN ('rec_order', 'off_order')
AND o.shop_id = #{shopId}
AND o.shop_id = #{shop_id}
GROUP BY TRIM(od.name)

SELECT COUNT(1)
FROM t_order o
WHERE
    o.order_time >= #{startTime}
    AND o.order_time < #{endTime}
    AND o.transac_status = 'success'
    AND o.order_receiving IN ('rec_order', 'off_order')

        AND o.shop_id = #{shopId}


        AND o.shop_id = #{shop_id}

SELECT IFNULL(SUM(od.quantity), 0)
FROM t_order_detail od
INNER JOIN t_order o ON od.`mId` = o.id
WHERE
    o.order_time >= #{startTime}
    AND o.order_time < #{endTime}
    AND od.quantity IS NOT NULL AND od.quantity > 0
    AND ( (od.total_price IS NOT NULL AND od.total_price > 0) OR IFNULL(od.line_type,'') = 'combo_component' )
    AND od.name IS NOT NULL AND TRIM(od.name) != ''
    AND o.transac_status = 'success'
    AND o.order_receiving IN ('rec_order', 'off_order')

        AND o.shop_id = #{shopId}


        AND o.shop_id = #{shop_id}
